const vk = (quelle, varianten) => Object.freeze({ art: "verkaufspreis", varianten: Object.freeze(varianten.map((v) => Object.freeze(v))), stand: STAND, quelle });
const groesse = (optionen, gruppe = T("Größe", "Size", "Taille", "Dimensione")) =>
  Object.freeze([Object.freeze({ gruppe, optionen: Object.freeze(optionen.map((o) => Object.freeze(o))) })]);
